import{_ as p,a0 as o,w as d,s as r,I as n,x as a,a1 as e,A as t,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"如何使用 Ansible 管理你的工作站配置 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 Ansible 管理你的工作站配置 | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 Ansible 管理你的工作站配置 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 Ansible 管理你的工作站配置 | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20180302 How to manage your workstation configuration with Ansible","title":"如何使用 Ansible 管理你的工作站配置","tag":"201901","desc":""},"relativePath":"201901/20180302 How to manage your workstation configuration with Ansible.md","filePath":"[post].md"}'),u={name:"201901/20180302 How to manage your workstation configuration with Ansible.md"};function b(g,s,h,c,k,m){const i=o("Link");return d(),r("div",null,[s[27]||(s[27]=n("h1",{id:"如何使用-ansible-管理你的工作站配置",tabindex:"-1"},[a("如何使用 Ansible 管理你的工作站配置 "),n("a",{class:"header-anchor",href:"#如何使用-ansible-管理你的工作站配置","aria-label":"Permalink to “如何使用 Ansible 管理你的工作站配置”"},"​")],-1)),s[28]||(s[28]=n("blockquote",null,[n("p",null,"在這個系列的第一篇中，學習一下管理筆記本電腦和台式機配置的基礎內容。")],-1)),s[29]||(s[29]=n("p",null,[n("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/computer_keyboard_laptop_development_code_woman.png?itok=vbYz6jjb",alt:""})],-1)),s[30]||(s[30]=n("p",null,[a("配置管理是服務器管理和 DevOps 的一個非常重要的方面。“"),n("ruby",null,[a("基礎架構即代碼"),n("rt",null,"infrastructure as code")]),a("”方法可以輕鬆地以各種配置部署服務器，並動態擴展組織的資源以滿足用户需求。但是，對於希望自動設置自己的筆記本電腦和台式機（工作站）的個人管理員的關注較少。")],-1)),n("p",null,[s[1]||(s[1]=a("在本系列中，我將向你展示如何通過 ",-1)),e(i,{href:"https://www.ansible.com/"},{default:t(()=>[...s[0]||(s[0]=[a("Ansible",-1)])]),_:1}),s[2]||(s[2]=a(" 自動化你的工作站設置，如果你想要或需要重新安裝你的機器，這可以讓你輕鬆恢復整個配置。此外，如果你有多個工作站，則可以使用相同的方法在每個工作站上進行相同的配置。在第一篇文章中，我們將為個人或工作計算機設置基本的配置管理，併為本系列的其餘部分奠定基礎。到本文結束時，你將會因此得到一個可以工作的環境。本系列之後的每篇文章都會自動化更多內容並增加複雜性。",-1))]),s[31]||(s[31]=l('<h3 id="為什麼用-ansible" tabindex="-1">為什麼用 Ansible？ <a class="header-anchor" href="#為什麼用-ansible" aria-label="Permalink to “為什麼用 Ansible？”">​</a></h3><p>有許多配置管理解決方案，包括 Salt Stack、Chef 和 Puppet。我更喜歡 Ansible，因為它在資源利用方面更輕量級，語法更容易閲讀，並且如果正確使用它可以徹底改變你的配置管理。Ansible 的輕量級特性與這個主題特別相關，因為我們可能不希望運行一整台服務器而只是為了自動化我們的筆記本電腦和台式機的設置。一般我們總是想要快一些；我們可以使用某些東西來快速啓動和運行，以在我們需要恢復的工作站或在多台機器之間同步我們的配置。我使用 Ansible 的具體方法（我將在本文中演示）非常適用於此，而不需要維護服務器。你只需下載配置並運行它。</p><h3 id="我的方法" tabindex="-1">我的方法 <a class="header-anchor" href="#我的方法" aria-label="Permalink to “我的方法”">​</a></h3><p>通常，Ansible 運行於中央服務器。它使用一個<ruby>庫存清單<rt>inventory</rt></ruby>文件，該文件是一個文本文件，其中包含我們希望 Ansible 管理的所有主機及其 IP 地址或域名的列表。這對於靜態環境非常有用，但對於工作站來説並不理想。原因是我們真的不知道我們的工作站在某一時刻的狀態。也許我關閉了台式電腦，或者筆記本電腦可能會被掛起並放在我的包裏。在任何一種情況下，Ansible 服務器都會抱怨，因為如果它們處於脱機狀態，Ansible 就無法聯繫到我的機器。我們更需要的是按需方式，我們通過利用 <code>ansible-pull</code> 來實現這一目標。<code>ansible-pull</code> 命令是 Ansible 的一個命令，允許你從 Git 倉庫下載配置並立即應用它。你不需要維護服務器或庫存清單；你只需運行 <code>ansible-pull</code> 命令，給它一個 Git 倉庫 URL，它將為你完成剩下的工作。</p><h3 id="起步" tabindex="-1">起步 <a class="header-anchor" href="#起步" aria-label="Permalink to “起步”">​</a></h3>',5)),n("p",null,[s[4]||(s[4]=a("首先，在要管理的計算機上安裝 Ansible。有一個問題是許多發行版都附帶了舊版本的 Ansible。根據經驗，你肯定希望獲得最新版本。Ansible 中經常引入新功能，如果你運行的是舊版本，則你在網上找到的示例語法可能無法正常運行，因為它使用的功能未在你安裝的版本中實現。甚至發佈的小版本都有很多新功能。其中一個例子是 ",-1)),s[5]||(s[5]=n("code",null,"dconf",-1)),s[6]||(s[6]=a(" 模組，它是從 Ansible 2.4 開始的新功能。如果你嘗試使用使用此模組的語法，除非你使用 2.4 或更新版本，否則會失敗。在 Ubuntu 及其衍生產品中，我們可以使用官方個人包存檔（",-1)),e(i,{href:"https://launchpad.net/ubuntu/+ppas"},{default:t(()=>[...s[3]||(s[3]=[a("PPA",-1)])]),_:1}),s[7]||(s[7]=a("）輕鬆安裝最新版本的 Ansible。以下命令可以解決這個問題：",-1))]),s[32]||(s[32]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install software-properties-common</span></span>
<span class="line"><span>sudo apt-add-repository ppa:ansible/ansible</span></span>
<span class="line"><span>sudo apt-get update</span></span>
<span class="line"><span>sudo apt-get install ansible</span></span></code></pre></div>`,1)),n("p",null,[s[9]||(s[9]=a("如果你沒有使用 Ubuntu，請參閲 ",-1)),e(i,{href:"http://docs.ansible.com/ansible/latest/intro_installation.html"},{default:t(()=>[...s[8]||(s[8]=[a("Ansible 的文檔",-1)])]),_:1}),s[10]||(s[10]=a(" 瞭解如何為你的平台獲取它。",-1))]),s[33]||(s[33]=l(`<p>接下來，我們需要一個 Git 倉庫來保存我們的配置。滿足此要求的最簡單方法是在 GitHub 上創建一個空的倉庫，或者如果有的話，也可以使用自己的 Git 服務器。為了簡單起見，我假設你正在使用 GitHub，因此如果你正在使用其他倉庫，請相應調整命令。在 GitHub 中創建一個倉庫；你最終會得到一個與此類似的倉庫 URL：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git@github.com:&lt;your_user_name&gt;/ansible.git</span></span></code></pre></div><p>將該倉庫克隆到你的本地工作目錄（忽略任何抱怨倉庫為空的消息）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git clone git@github.com:&lt;your_user_name&gt;/ansible.git</span></span></code></pre></div><p>現在我們有了一個可以使用的空倉庫。將你的工作目錄切換到倉庫（例如 <code>cd ./ansible</code>），並在你喜歡的文本編輯器中創建名為 <code>local.yml</code> 的文件。將以下配置放在該文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- hosts: localhost</span></span>
<span class="line"><span>  become: true</span></span>
<span class="line"><span>  tasks:</span></span>
<span class="line"><span>  - name: Install htop</span></span>
<span class="line"><span>    apt: name=htop</span></span></code></pre></div><p>你剛剛創建的文件被稱為<ruby>劇本<rt>playbook</rt></ruby>，安裝 <code>htop</code> 的指令（我任意選擇的一個包作為例子）被稱為<ruby>動作<rt>play</rt></ruby>。劇本本身是一個 YAML 格式的文件，它是一種易於閲讀的標記語言。對 YAML 的完整講述超出了本文的範圍，但你無需專業理解即可熟練使用 Ansible。該配置易於閲讀；只需查看此文件，你就可以輕鬆理解我們正在安裝的 <code>htop</code> 軟件包。要注意一下最後一行的 <code>apt</code> 模組，它只適用於基於 Debian 的系統。如果你使用的是 Red Hat 平台，你可以將其更改為 <code>yum</code> 而不是 <code>apt</code>，或者如果你正在使用 Fedora，則將其更改為 <code>dnf</code>。<code>name</code> 行只是提供有關我們任務的信息，並將顯示在輸出中。因此，你需要確保名稱具有描述性，以便在需要對多個動作進行故障排除時很容易找到。</p><p>接下來，讓我們將新文件提交到我們的倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git add local.yml</span></span>
<span class="line"><span>git commit -m &quot;initial commit&quot;</span></span>
<span class="line"><span>git push origin master</span></span></code></pre></div><p>現在我們的新劇本應該出現在我們的 GitHub 上的倉庫中。我們可以使用以下命令應用我們創建的劇本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ansible-pull -U https://github.com/&lt;your_user_name&gt;/ansible.git</span></span></code></pre></div><p>如果執行正確，<code>htop</code>包應該會安裝在你的系統上。你可能會在開頭附近看到一些警告，抱怨缺少庫存清單文件。這很好，因為我們沒有使用庫存清單文件（我們也不需要這樣做）。在輸出結束時，它將概述它做的內容。如果 <code>htop</code> 安裝正確，你應該在輸出的最後一行看到 <code>changed = 1</code>。</p><p>它是如何工作的呢？<code>ansible-pull</code> 命令使用了 <code>-U</code> 選項，它需要一個倉庫 URL。出於安全考慮，我給它提供了倉庫 URL 的 https 版本，因為我不希望任何主機對倉庫具有寫訪問權限（默認情況下 https 是隻讀的）。<code>local.yml</code> 是預設的劇本名稱，因此我們不需要為劇本提供文件名：如果它在倉庫的根目錄中找到名為 <code>local.yml</code> 的劇本，它將自動運行它。接下來，我們在命令前面使用了 <code>sudo</code>，因為我們正在修改系統。</p><p>讓我們繼續為我們的劇本添加更多的包。我將添加兩個包，使它看起來像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- hosts: localhost</span></span>
<span class="line"><span>  become: true</span></span>
<span class="line"><span>  tasks:</span></span>
<span class="line"><span>  - name: Install htop</span></span>
<span class="line"><span>    apt: name=htop</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  - name: Install mc</span></span>
<span class="line"><span>    apt: name=mc</span></span>
<span class="line"><span>   </span></span>
<span class="line"><span>  - name: Install tmux</span></span>
<span class="line"><span>    apt: name=tmux</span></span></code></pre></div><p>我添加了更多的動作（任務）來安裝另外兩個包，<code>mc</code> 和 <code>tmux</code>。在此劇本中選擇安裝的哪些軟件包並不重要；我只是隨意挑選這些。你應該安裝你希望所有的系統都具有的軟件包。唯一需要注意的是，在你分發前，你必須知道那個包存在於軟件倉庫中。</p><p>在我們提交併應用這個更新的劇本之前，我們應該整理一下它。它可以很好地工作，但（説實話）它看起來有點混亂。讓我們嘗試在一個動作中安裝所有三個包。用下面這個替換你的 <code>local.yml</code> 的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- hosts: localhost</span></span>
<span class="line"><span>  become: true</span></span>
<span class="line"><span>  tasks:</span></span>
<span class="line"><span>  - name: Install packages</span></span>
<span class="line"><span>    apt: name={{item}}</span></span>
<span class="line"><span>    with_items:</span></span>
<span class="line"><span>      - htop</span></span>
<span class="line"><span>      - mc</span></span>
<span class="line"><span>      - tmux</span></span></code></pre></div><p>現在看起來更乾淨、更有效率了。我們使用 <code>with_items</code> 將我們的包列表合併為一個動作。如果我們想要添加其他包，我們只需添加另一個帶有連字符和包名稱的行。可以把 <code>with_items</code> 看做類似於 <code>for</code> 循環。我們列出的每個包都將安裝。</p><p>將我們的新更改提交回倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git add local.yml</span></span>
<span class="line"><span>git commit -m &quot;added additional packages, cleaned up formatting&quot;</span></span>
<span class="line"><span>git push origin master</span></span></code></pre></div><p>現在我們可以運行我們的劇本以接受新的新配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ansible-pull -U https://github.com/&lt;your_user_name&gt;/ansible.git</span></span></code></pre></div><p>不可否認，這個例子還沒有做多少事情；它所做的就是安裝一些軟件包。你可以使用包管理器更快地安裝這些包。然而，隨着這個系列的繼續，這些例子將變得更加複雜，我們將自動化更多的東西。最後，你創建的 Ansible 配置將自動執行越來越多的任務。例如，我自己使用的那個配置可以自動安裝數百個軟件包、設置cron 作業、處理桌面配置等等。</p><p>從我們迄今為止所取得的成就來看，你可能已經有了大概瞭解。我們所要做的就是創建一個倉庫，在該倉庫中放置一個劇本，然後利用 <code>ansible-pull</code> 命令拉取該倉庫並將其應用到我們的機器上。我們不需要設置服務器。將來，如果我們想要更改配置，我們可以拉取該倉庫、更新它，然後將其推回到我們的倉庫並應用它。如果我們要設置新機器，我們只需要安裝 Ansible 並應用配置。</p>`,25)),n("p",null,[s[12]||(s[12]=a("在下一篇文章中，我們將通過 cron 和一些其他項目進一步自動化。與此同時，我已將本文的代碼複製到 ",-1)),e(i,{href:"https://github.com/jlacroix82/ansible_article"},{default:t(()=>[...s[11]||(s[11]=[a("我的 GitHub 倉庫",-1)])]),_:1}),s[13]||(s[13]=a(" 中，以便你可以用你的語法對比一下我的。隨着我們的進展，我會不斷更新代碼。",-1))]),s[34]||(s[34]=n("hr",null,null,-1)),n("p",null,[s[15]||(s[15]=a("via: ",-1)),e(i,{href:"https://opensource.com/article/18/3/manage-workstation-ansible"},{default:t(()=>[...s[14]||(s[14]=[a("https://opensource.com/article/18/3/manage-workstation-ansible",-1)])]),_:1})]),n("p",null,[s[19]||(s[19]=a("作者：",-1)),e(i,{href:"https://opensource.com/users/jlacroix"},{default:t(()=>[...s[16]||(s[16]=[a("Jay LaCroix",-1)])]),_:1}),s[20]||(s[20]=a(" 譯者：",-1)),e(i,{href:"https://github.com/"},{default:t(()=>[...s[17]||(s[17]=[a("wxy",-1)])]),_:1}),s[21]||(s[21]=a(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:t(()=>[...s[18]||(s[18]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[24]||(s[24]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[22]||(s[22]=[a("LCTT",-1)])]),_:1}),s[25]||(s[25]=a(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:t(()=>[...s[23]||(s[23]=[a("Linux中國",-1)])]),_:1}),s[26]||(s[26]=a(" 榮譽推出",-1))])])}const C=p(u,[["render",b]]);export{A as __pageData,C as default};
